#!/usr/bin/env python3
"""Gallery cover motif audit (ROUND-4 gap #6): per city, the glyph → motif pairs the generated cards carry
(data-gl = the card glyph, data-m = imagery.motifOf: the place's kind id). Writes design/beta/eval/w5/designer/MOTIF-AUDIT.md.
    python3 design/beta/tools/motif-audit.py"""
import collections, glob, os, re
R = os.path.join(os.path.dirname(os.path.abspath(__file__)), '..', '..', '..')
JAPAN = {'tokyo', 'kyoto', 'osaka', 'okinawa', 'hokkaido'}
out = ['# Gallery cover motif audit — W5 (ROUND-4 gap #6)', '',
       'Generated by `design/beta/tools/motif-audit.py` from the built pages. `glyph` = the card glyph (`data-gl`, keyed on the',
       'first collection/cuisine id); `motif` = the cover art (`data-m`, `imagery.motifOf`: the first *kind* id in the record\'s own',
       'collection order — theme ids such as ANIME/POP/FREE/ICON only decide when no kind id exists). Never keywords.',
       '`worship` draws the shrine gate on Japan pages and a generic spire elsewhere.', '']
tot = collections.Counter(); changed_tot = 0; n_tot = 0
rows = []
for f in sorted(glob.glob(os.path.join(R, 'beta', 'cities', '*.html')) + [os.path.join(R, 'beta', 'cleveland.html')] + glob.glob(os.path.join(R, 'beta', '*', '*', '*.html'))):
    h = open(f, encoding='utf8').read()
    m = re.search(r'<main id="main" data-city="([^"]+)"', h)
    if not m: continue
    city = m.group(1)
    pairs = collections.Counter(); changed = []
    for a in re.finditer(r'<li class="pl[^"]*" id="p-([^"]*)"([^>]*)>.*?<h3 class="pl-n"><a[^>]*>(.*?)</a>', h, re.S):
        gl = re.search(r'data-gl="([^"]*)"', a.group(2)); mo = re.search(r'data-m="([^"]*)"', a.group(2))
        if not gl or not mo: continue
        gl, mo = gl.group(1), mo.group(1)
        if mo == 'worship': mo = 'worship→torii' if city in JAPAN else 'worship→spire'
        pairs[(gl, mo)] += 1
        if gl != mo.split('→')[-1]: changed.append(re.sub('<[^>]+>', '', a.group(3)).strip())
    n = sum(pairs.values())
    if not n: continue
    n_tot += n; changed_tot += len(changed); tot.update(pairs)
    top = ', '.join(f'{g}→{mo} {c}' for (g, mo), c in pairs.most_common(5))
    rows.append(f'| {city} | {n} | {len(changed)} | {top} | {"; ".join(changed[:3])}{" …" if len(changed) > 3 else ""} |')
out += [f'**{n_tot} cards on {len(rows)} city pages; {changed_tot} now draw their kind instead of their glyph.**', '',
        '## All pages — the 20 most common glyph → motif pairs', '', '| glyph → motif | cards |', '|---|---:|']
out += [f'| {g} → {mo}{"  (changed)" if g != mo.split("→")[-1] else ""} | {c} |' for (g, mo), c in tot.most_common(20)]
out += ['', '## Per city', '', '| city | cards | changed | top 5 pairs | first changed cards |', '|---|---:|---:|---|---|'] + rows
P = os.path.join(R, 'design', 'beta', 'eval', 'w5', 'designer', 'MOTIF-AUDIT.md')
os.makedirs(os.path.dirname(P), exist_ok=True); open(P, 'w').write('\n'.join(out) + '\n'); print('motif-audit:', n_tot, 'cards,', changed_tot, 'changed →', P)
